import { createContext, use } from 'react';

import type { SelectHeaderRowEvent, SelectRowEvent } from '../types';

export interface RowSelectionContextValue {
  readonly isRowSelected: boolean;
  readonly isRowSelectionDisabled: boolean;
}

export const RowSelectionContext = createContext<RowSelectionContextValue | undefined>(undefined);
RowSelectionContext.displayName = 'RowSelectionContext';

export const RowSelectionChangeContext = createContext<
  // oxlint-disable-next-line typescript/no-explicit-any
  ((selectRowEvent: SelectRowEvent<any>) => void) | undefined
>(undefined);
RowSelectionChangeContext.displayName = 'RowSelectionChangeContext';

export function useRowSelection() {
  const rowSelectionContext = use(RowSelectionContext);
  const rowSelectionChangeContext = use(RowSelectionChangeContext);

  if (rowSelectionContext === undefined || rowSelectionChangeContext === undefined) {
    throw new Error('useRowSelection must be used within renderCell');
  }

  return {
    isRowSelectionDisabled: rowSelectionContext.isRowSelectionDisabled,
    isRowSelected: rowSelectionContext.isRowSelected,
    onRowSelectionChange: rowSelectionChangeContext
  };
}

export interface HeaderRowSelectionContextValue {
  readonly isRowSelected: boolean;
  readonly isIndeterminate: boolean;
}

export const HeaderRowSelectionContext = createContext<HeaderRowSelectionContextValue | undefined>(
  undefined
);
HeaderRowSelectionContext.displayName = 'HeaderRowSelectionContext';

export const HeaderRowSelectionChangeContext = createContext<
  ((selectRowEvent: SelectHeaderRowEvent) => void) | undefined
>(undefined);
HeaderRowSelectionChangeContext.displayName = 'HeaderRowSelectionChangeContext';

export function useHeaderRowSelection() {
  const headerRowSelectionContext = use(HeaderRowSelectionContext);
  const headerRowSelectionChangeContext = use(HeaderRowSelectionChangeContext);

  if (headerRowSelectionContext === undefined || headerRowSelectionChangeContext === undefined) {
    throw new Error('useHeaderRowSelection must be used within renderHeaderCell');
  }

  return {
    isIndeterminate: headerRowSelectionContext.isIndeterminate,
    isRowSelected: headerRowSelectionContext.isRowSelected,
    onRowSelectionChange: headerRowSelectionChangeContext
  };
}

import { useState } from 'react';
import { page, userEvent } from 'vitest/browser';

import { DataGrid, SelectColumn } from '../../src';
import type { Column } from '../../src';

const rows = page.getRow();
const headerCheckbox = page.getSelectAllCheckbox();

interface Row {
  id: number;
}

const columns: readonly Column<Row>[] = [
  SelectColumn,
  {
    key: 'id',
    name: 'ID'
  }
];

const defaultRows: readonly Row[] = [{ id: 1 }, { id: 2 }, { id: 3 }];

function rowKeyGetter(row: Row) {
  return row.id;
}

function RowSelectionTest({
  initialRows,
  isRowSelectionDisabled
}: {
  initialRows: readonly Row[];
  isRowSelectionDisabled?: (row: Row) => boolean;
}) {
  const [selectedRows, setSelectedRows] = useState((): ReadonlySet<number> => new Set());

  return (
    <DataGrid
      rowKeyGetter={rowKeyGetter}
      columns={columns}
      rows={initialRows}
      selectedRows={selectedRows}
      isRowSelectionDisabled={isRowSelectionDisabled}
      onSelectedRowsChange={setSelectedRows}
    />
  );
}

function setup(initialRows = defaultRows) {
  return page.render(<RowSelectionTest initialRows={initialRows} />);
}

function testSelection(rowIdx: number, isSelected: boolean) {
  return expect
    .element(rows.nth(rowIdx))
    .toHaveAttribute('aria-selected', isSelected ? 'true' : 'false');
}

async function toggleSelection(rowIdx: number, shift = false, force = false) {
  const checkbox = rows.nth(rowIdx).getByRole('checkbox', { name: 'Select' });
  if (shift) await userEvent.keyboard('{Shift>}');
  await userEvent.click(checkbox, { force });
  if (shift) await userEvent.keyboard('{/Shift}');
}

test('toggle selection when checkbox is clicked', async () => {
  await setup();
  await toggleSelection(0);
  await testSelection(0, true);
  await toggleSelection(1);
  await testSelection(1, true);

  await toggleSelection(0);
  await testSelection(0, false);
  await toggleSelection(1);
  await testSelection(1, false);
});

test('toggle selection using keyboard', async () => {
  await setup();
  await testSelection(0, false);
  await userEvent.click(rows.nth(0).getByRole('checkbox', { name: 'Select' }));
  await testSelection(0, true);
  await userEvent.keyboard(' ');
  await testSelection(0, false);
  await userEvent.keyboard(' ');
  await testSelection(0, true);
  await userEvent.keyboard('{arrowdown} ');
  await testSelection(1, true);
  await userEvent.keyboard('{arrowup} ');
  await testSelection(0, false);
});

test('should partially select header checkbox', async () => {
  await setup();
  await expect.element(headerCheckbox).not.toBeChecked();
  await expect.element(headerCheckbox).not.toBePartiallyChecked();

  await toggleSelection(0);
  await expect.element(headerCheckbox).not.toBeChecked();
  await expect.element(headerCheckbox).toBePartiallyChecked();

  await toggleSelection(1);
  await expect.element(headerCheckbox).not.toBeChecked();
  await expect.element(headerCheckbox).toBePartiallyChecked();

  await toggleSelection(2);
  await expect.element(headerCheckbox).toBeChecked();
  await expect.element(headerCheckbox).not.toBePartiallyChecked();

  await toggleSelection(0);
  await expect.element(headerCheckbox).not.toBeChecked();
  await expect.element(headerCheckbox).toBePartiallyChecked();

  await userEvent.click(headerCheckbox);
  await testSelection(0, false);
  await testSelection(1, false);
  await testSelection(2, false);

  await userEvent.click(headerCheckbox);
  await testSelection(0, true);
  await testSelection(1, true);
  await testSelection(2, true);
});

test('should not select row when isRowSelectionDisabled returns true', async () => {
  await page.render(
    <RowSelectionTest initialRows={defaultRows} isRowSelectionDisabled={(row) => row.id === 2} />
  );
  await toggleSelection(0);
  await testSelection(0, true);
  await toggleSelection(1, false, true); // force click even if disabled
  await testSelection(1, false);
  await toggleSelection(2);
  await testSelection(2, true);

  await userEvent.click(headerCheckbox);
  await toggleSelection(0);
  await toggleSelection(2, true);
  await testSelection(0, true);
  await testSelection(1, false);
  await testSelection(2, true);
});

test('select/deselect all rows when header checkbox is clicked', async () => {
  await setup();
  await expect.element(headerCheckbox).not.toBeChecked();
  await userEvent.click(headerCheckbox);
  await testSelection(0, true);
  await testSelection(1, true);
  await testSelection(2, true);

  // deselecting a row should toggle header
  await toggleSelection(0);
  await expect.element(headerCheckbox).not.toBeChecked();
  await toggleSelection(0);
  await expect.element(headerCheckbox).toBeChecked();

  await userEvent.click(headerCheckbox);
  await testSelection(0, false);
  await testSelection(1, false);
  await testSelection(2, false);
});

test('header checkbox is not checked when there are no rows', async () => {
  await setup([]);
  await expect.element(headerCheckbox).not.toBeChecked();
});

test('header checkbox is not necessarily checked when selectedRows.size === rows.length', async () => {
  await page.render(
    <DataGrid
      rowKeyGetter={rowKeyGetter}
      columns={columns}
      rows={defaultRows}
      selectedRows={new Set([1, 2, 4])}
    />
  );

  await expect.element(headerCheckbox).not.toBeChecked();
});

test('header checkbox is not necessarily checked when selectedRows.size > rows.length', async () => {
  await page.render(
    <DataGrid
      rowKeyGetter={rowKeyGetter}
      columns={columns}
      rows={defaultRows}
      selectedRows={new Set([1, 2, 4, 5])}
    />
  );

  await expect.element(headerCheckbox).not.toBeChecked();
});

test('extra keys are preserved when updating the selectedRows Set', async () => {
  const initialSet = new Set([-1, 0, 99]);
  let set = initialSet;

  function Test() {
    const [selectedRows, setSelectedRows] = useState<ReadonlySet<number>>(initialSet);

    function onSelectedRowsChange(selectedRows: Set<number>) {
      setSelectedRows(selectedRows);
      set = selectedRows;
    }

    return (
      <DataGrid
        rowKeyGetter={rowKeyGetter}
        columns={columns}
        rows={defaultRows}
        selectedRows={selectedRows}
        onSelectedRowsChange={onSelectedRowsChange}
      />
    );
  }

  await page.render(<Test />);

  await toggleSelection(1);
  expect(set).toStrictEqual(new Set([...initialSet, 2]));

  await userEvent.click(headerCheckbox);
  expect(set).toStrictEqual(initialSet);

  await userEvent.click(headerCheckbox);
  expect(set).toStrictEqual(new Set([...initialSet, 1, 2, 3]));

  await userEvent.click(headerCheckbox);
  expect(set).toStrictEqual(initialSet);

  await toggleSelection(1);
  expect(set).toStrictEqual(new Set([...initialSet, 2]));

  await toggleSelection(1);
  expect(set).toStrictEqual(initialSet);
});

test('select/deselect rows using shift click', async () => {
  await setup();

  // forward selection
  await toggleSelection(0);
  await toggleSelection(2, true);
  await testSelection(0, true);
  await testSelection(1, true);
  await testSelection(2, true);

  // forward deselection
  await toggleSelection(0);
  await toggleSelection(2, true);
  await testSelection(0, false);
  await testSelection(1, false);
  await testSelection(2, false);

  // backward selection
  await toggleSelection(2);
  await toggleSelection(0, true);
  await testSelection(0, true);
  await testSelection(1, true);
  await testSelection(2, true);

  // backward deselection
  await toggleSelection(2);
  await toggleSelection(0, true);
  await testSelection(0, false);
  await testSelection(1, false);
  await testSelection(2, false);
});

test('select rows using shift space', async () => {
  await setup();
  await userEvent.click(page.getCell({ name: '1' }));
  await userEvent.keyboard('{Shift>} {/Shift}');
  await testSelection(0, true);
  await userEvent.keyboard(' ');
  await testSelection(0, true);
  await userEvent.keyboard('{Shift>} {/Shift}');
  await testSelection(0, false);
});

const assert  = require('assert');
const brains  = require('./helpers/brains');
const Browser = require('../src');


describe('Selection', function() {
  const browser = new Browser();

  before(function() {
    brains.static('/browser/walking', `
      <html>
        <head>
          <script src="/scripts/jquery.js"></script>
          <script src="/scripts/sammy.js"></script>
          <script src="/browser/app.js"></script>
        </head>
        <body>
          <div id="main">
            <a href="/browser/dead">Kill</a>
            <form action="#/dead" method="post">
              <label>Email <input type="text" name="email"></label>
              <label>Password <input type="password" name="password"></label>
              <button>Sign Me Up</button>
              <input type="reset" value="Reset">
              <input type="button" value="A generic button">
              <input type="submit" value="Send">
            </form>
          </div>
          <div class="now">Walking Aimlessly</div>
          <button>Do not press!</button>
        </body>
      </html>`);

    brains.static('/browser/app.js', `
      Sammy('#main', function(app) {
        app.get('#/', function(context) {
          document.title = 'The Living';
        });
        app.get('#/dead', function(context) {
          context.swap('The Living Dead');
        });
        app.post('#/dead', function(context) {
          document.title = 'Signed up';
        });
      });
      $(function() { Sammy('#main').run('#/'); });
    `);

    return brains.ready();
  });

  before(function() {
    return browser.visit('/browser/walking');
  });


  describe('queryAll', function() {
    it('should return array of nodes', function() {
      const nodes = browser.queryAll('.now');
      assert.equal(nodes.length, 1);
    });
  });

  describe('query method', function() {
    it('should return single node', function() {
      const node = browser.query('.now');
      assert.equal(node.tagName, 'DIV');
    });
  });

  describe('the tricky ID', function() {
    let root;
    before(function() {
      root = browser.document.getElementById('main');
    });

    it('should find child from id', function() {
      const nodes = root.querySelectorAll('#main button');
      assert.equal(nodes.item(0).textContent, 'Sign Me Up');
    });

    it('should find child from parent', function() {
      const nodes = root.querySelectorAll('button');
      assert.equal(nodes[0].textContent, 'Sign Me Up');
    });

    it('should not re-find element itself', function() {
      const nodes = root.querySelectorAll('#main');
      assert.equal(nodes.length, 0);
    });

    it('should not find children of siblings', function() {
      const nodes = root.querySelectorAll('button');
      assert.equal(nodes.length, 1);
    });
  });

  describe('query text', function() {
    it('should query from document', function() {
      assert.equal(browser.text('.now'), 'Walking Aimlessly');
    });
    it('should query from context (exists)', function() {
      assert.equal(browser.text('.now'), 'Walking Aimlessly');
    });
    it('should query from context (unrelated)', function() {
      assert.equal(browser.text('.now', browser.querySelector('form')), '');
    });
    it('should combine multiple elements', function() {
      assert.equal(browser.text('form label'), 'Email Password');
    });
  });

  describe('query html', function() {
    it('should query from document', function() {
      assert.equal(browser.html('.now'), '<div class="now">Walking Aimlessly</div>');
    });
    it('should query from context (exists)', function() {
      assert.equal(browser.html('.now', browser.body), '<div class="now">Walking Aimlessly</div>');
    });
    it('should query from context (unrelated)', function() {
      assert.equal(browser.html('.now', browser.querySelector('form')), '');
    });
    it('should combine multiple elements', function() {
      assert.equal(browser.html('title, #main a'), '<title>The Living</title><a href="/browser/dead">Kill</a>');
    });
  });


  describe('button', function() {
    describe('when passed a valid HTML element', function() {
      it('should return the already queried element', function() {
        const elem = browser.querySelector('button');
        assert.equal(browser.button(elem), elem);
      });
    });

    describe('when passed a text on button', function() {
      it('should return the button with equally text content', function() {
        const elem = browser.querySelector('.now + button');
        assert.equal(browser.button('Do not press!'), elem);
      });
      it('should find button-like inputs', function() {
        const resetButton = browser.querySelector('form input[type="reset"]');
        const genericButton = browser.querySelector('form input[type="button"]');
        const submitButton = browser.querySelector('form input[type="submit"]');
        assert.equal(browser.button('Reset'), resetButton);
        assert.equal(browser.button('A generic button'), genericButton);
        assert.equal(browser.button('Send'), submitButton);
      });
    });
  });

  describe('link', function() {
    describe('when passed a valid HTML element', function() {
      it('should return the already queried element', function() {
        const elem = browser.querySelector('a:first-child');
        assert.equal(browser.link(elem), elem);
      });
    });
  });

  describe('field', function() {
    describe('when passed a valid HTML element', function() {
      it('should return the already queried element', function() {
        const elem = browser.querySelector('input[name="email"]');
        assert.equal(browser.field(elem), elem);
      });
    });
  });


  describe('jQuery', function() {
    let $;
    before(function() {
      $ = browser.evaluate('window.jQuery');
    });

    it('should query by id', function() {
      assert.equal($('#main').size(), 1);
    });
    it('should query by element name', function() {
      assert.equal($('form').attr('action'), '#/dead');
    });
    it('should query by element name (multiple)', function() {
      assert.equal($('label').size(), 2);
    });
    it('should query with descendant selectors', function() {
      assert.equal($('body #main a').text(), 'Kill');
    });
    it('should query in context', function() {
      assert.equal($('body').find('#main a', 'body').text(), 'Kill');
    });
    it('should query in context with find()', function() {
      assert.equal($('body').find('#main a').text(), 'Kill');
    });
  });


  after(function() {
    browser.destroy();
  });

});

// Support for element focus.


const DOM = require('./index');
const { idlUtils }    = require('./impl');

const FOCUS_ELEMENTS = ['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON', 'ANCHOR'];


// The element in focus.
//
// If no element has the focus, return the document.body.
DOM.HTMLDocument.prototype.__defineGetter__('activeElement', function() {
  return this._inFocus || this.body;
});

// Change the current element in focus (or null for blur)
function setFocus(document, element) {
  const inFocus = document._inFocus;
  if (element !== inFocus) {
    const inputElementImpl = idlUtils.implForWrapper(element || inFocus);
    if (inFocus) {
      const onblur = document.createEvent('HTMLEvents');
      onblur.initEvent('blur', false, false);
      const dispatchResult = inFocus.dispatchEvent(onblur);
      inFocus._blur && inFocus._blur(onblur);
    }
    if (element) { // null to blur
      const onfocus = document.createEvent('HTMLEvents');
      onfocus.initEvent('focus', false, false);
      const dispatchResult = element.dispatchEvent(onfocus);
      element._focus && element._focus(onfocus);
      document._inFocus = element;
      document.defaultView.browser.emit('focus', element);
    }
  }
}

// All HTML elements have a no-op focus/blur methods.
DOM.HTMLElement.prototype.focus = function() {
};
DOM.HTMLElement.prototype.blur = function() {
};

// Input controls have active focus/blur elements.  JSDOM implements these as
// no-op, so we have to over-ride each prototype individually.
const CONTROLS = [DOM.HTMLInputElement, DOM.HTMLSelectElement, DOM.HTMLTextAreaElement, DOM.HTMLButtonElement, DOM.HTMLAnchorElement];

CONTROLS.forEach(function(elementType) {
  elementType.prototype.focus = function() {
    setFocus(this.ownerDocument, this);
  };

  elementType.prototype.blur = function() {
    setFocus(this.ownerDocument, null);
  };

  // Capture the autofocus element and use it to change focus
  const setAttribute = elementType.prototype.setAttribute;
  elementType.prototype.setAttribute = function(name, value) {
    setAttribute.call(this, name, value);
    if (name === 'autofocus') {
      const document = this.ownerDocument;
      if (~FOCUS_ELEMENTS.indexOf(this.tagName) && !document._inFocus)
        this.focus();
    }
  };
});


// When changing focus onto form control, store the current value.  When changing
// focus to different control, if the value has changed, trigger a change event.
const INPUTS = [DOM.HTMLInputElement, DOM.HTMLTextAreaElement, DOM.HTMLSelectElement];

INPUTS.forEach(function(elementType) {
  elementType.prototype._focus = function(event) {
    const element       = event.target;
    element._focusValue = element.value || '';
  };

  elementType.prototype._blur = function(event) {
    const element     = event.target;
    const focusValue  = element._focusValue;
    if (focusValue !== element.value) { // null == undefined
      const change = element.ownerDocument.createEvent('HTMLEvents');
      change.initEvent('change', false, false);
      element.dispatchEvent(change);
    }
  };
});


// HTMLForm listeners
const _blur = function(event) {
  const element     = event.target;
  const focusValue  = element._focusValue;
  if (focusValue !== element.value) { // null == undefined
    const change = element.ownerDocument.createEvent('HTMLEvents');
    change.initEvent('change', false, false);
    element.dispatchEvent(change);
  }
}

const _focus = function(event) {
  const element       = event.target;
  element._focusValue = element.value || '';
};
